// Pega todos os itens que vieram do banco
const allMessages = items.map(item => {
  const msg = item.json.message;
  let text = "";

  if (msg.type === 'ai') {
    try {
      // Tenta extrair apenas a "resposta_texto" do JSON da IA
      const contentObj = JSON.parse(msg.content);
      text = contentObj.resposta_texto || msg.content;
    } catch (e) {
      // Se não for JSON, usa o conteúdo bruto
      text = msg.content;
    }
    return `ai: ${text}`;
  } else {
    // Se for humano, pega o conteúdo direto
    return `human: ${msg.content}`;
  }
});

// Junta tudo com uma quebra de linha entre cada mensagem
return {
  historico_limpo: allMessages.join('\n')
};
